  function renderLibrary(){return `<section class="card hero"><div class="eyebrow">SHAXSIY KUTUBXONA · 5 KITOB</div><h2>Kitoblarim</h2><p>Arxivdan joylangan 5 ta asl PDF · 234 sahifa. Internet kerak emas.</p><span class="badge">OFFLINE · TAYYOR</span></section><section class="card"><label class="label" for="book-search">Kitob qidirish</label><input id="book-search" type="search" placeholder="Kitob nomini yozing…" autocomplete="off"><p id="book-no-results" hidden class="muted">Kitob topilmadi.</p>${catalogSlots.map(i=>{const b=BUNDLED[i];return `<div class="item book-row" data-book-name="${html(b.title+' '+b.author)}"><img class="book-cover" src="books/${i}/cover.webp" alt=""><div class="grow"><strong>${html(b.title)}</strong><small>${html(b.author)}</small><small>${bookPage(i)} / ${b.pages} sahifa · ${formatTime(total('content','book-'+i,30))}</small><small class="offline-label">Offline tayyor</small></div><button class="secondary" data-act="book-open" data-id="${i}">O‘qish</button></div>`}).join('')}</section>${imported('book').length||Object.keys(model.customBooks).length?`<section class="card"><h3>Keyin qo‘shilgan shaxsiy fayllar</h3>${[...Object.entries(model.customBooks),...imported('book').map(i=>[i,bookName(i)])].map(([i,n])=>`<div class="item book-row" data-book-name="${html(n)}"><div class="grow">${html(n)}</div><button class="secondary" data-act="book-open" data-id="${i}">Ochish</button></div>`).join('')}</section>`:''}<section class="card"><button data-act="book-add">+ Shaxsiy PDF qo‘shish</button></section>${importInfo()}`;}
