  function renderReader(){return `<section class="card reader-card"><div class="reader-head"><div class="grow"><div class="eyebrow">PDF MUTOLAA</div><h2>${html(bookName(currentBook))}</h2><small class="muted">${bundled(currentBook)?html(BUNDLED[currentBook].author)+' · Offline': 'Shaxsiy PDF'}</small></div><div class="reader-time"><small>Bugun</small><strong id="time-book-${currentBook}">${formatTime(total('content','book-'+currentBook))}</strong></div></div><div id="pdf-stage" class="reader-stage" hidden><button id="pdf-prev" class="reader-arrow" data-act="pdf-prev" aria-label="Oldingi sahifa" title="Oldingi sahifa">&#10094;</button><div class="pdf-view" id="pdf-view" hidden><img id="pdf-image" alt="PDF sahifasi" draggable="false"></div><button id="pdf-next" class="reader-arrow" data-act="pdf-next" aria-label="Keyingi sahifa" title="Keyingi sahifa">&#10095;</button></div><p id="pdf-message" class="muted reader-message" role="status">PDF ochilmoqda…</p><div id="pdf-toolbar" class="reader-tools" hidden><div class="reader-progress" role="progressbar" aria-label="Mutolaa jarayoni" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div id="pdf-progress-fill"></div></div><div class="row between reader-controls"><span id="pdf-status" class="muted sm" aria-live="polite"></span><div class="row zoom-tools"><button id="zoom-out" class="secondary" data-act="pdf-zoomout" aria-label="Kichraytirish">−</button><button id="zoom-reset" class="secondary" data-act="pdf-zoomreset" aria-label="Asl kattalik">${pdfZoom}%</button><button id="zoom-in" class="secondary" data-act="pdf-zoomin" aria-label="Kattalashtirish">+</button></div><div class="row jump-tools"><input type="number" inputmode="numeric" id="pdf-number" min="1" value="${bookPage(currentBook)}" aria-label="Sahifa raqami"><button class="secondary" data-act="pdf-jump">O‘tish</button></div></div></div><details class="reader-extra"><summary>Mutolaa sozlamalari</summary><div class="row wrap"><button class="secondary" data-act="pdf-refresh">Qayta ochish</button>${!bundled(currentBook)&&currentBook<49?'<button class="secondary" data-act="pdf-pick">PDF tanlash</button>':''}<button class="secondary" data-act="manual-time" data-id="book-${currentBook}">Vaqt kiritish</button></div></details></section>`;}
  let pdfZoom=100,pdfRequest=0,pdfRequestedPage=1;
  function readerControls(page){const prev=document.getElementById('pdf-prev'),next=document.getElementById('pdf-next'),status=document.getElementById('pdf-status'),fill=document.getElementById('pdf-progress-fill');if(prev)prev.disabled=page<=1;if(next)next.disabled=page>=pdfCount;if(status)status.textContent=page+' / '+pdfCount;if(fill)fill.style.width=(100*page/pdfCount)+'%';const num=document.getElementById('pdf-number');if(num){num.value=page;num.max=pdfCount;}const progress=fill?.parentElement;if(progress)progress.setAttribute('aria-valuenow',String(Math.round(100*page/pdfCount)));const reset=document.getElementById('zoom-reset'),out=document.getElementById('zoom-out'),inn=document.getElementById('zoom-in');if(reset)reset.textContent=pdfZoom+'%';if(out)out.disabled=pdfZoom<=100;if(inn)inn.disabled=pdfZoom>=250;}
  function showPdf(page=bookPage(currentBook)){const request=++pdfRequest,bid=currentBook;pdfReady=false;const msg=document.getElementById('pdf-message'),toolbar=document.getElementById('pdf-toolbar'),stage=document.getElementById('pdf-stage'),view=document.getElementById('pdf-view'),img=document.getElementById('pdf-image');if(!msg||!toolbar||!stage||!view||!img)return;pdfCount=getPdfCount();toolbar.hidden=!pdfCount;stage.hidden=!pdfCount;img.onload=null;img.onerror=null;if(!pdfCount){view.hidden=true;msg.hidden=false;msg.textContent='PDF ochilmadi. Mutolaa sozlamalaridan PDF tanlang yoki qayta oching.';return;}page=Math.max(1,Math.min(pdfCount,Math.floor(Number(page)||1)));pdfRequestedPage=page;readerControls(page);msg.hidden=false;msg.textContent='Sahifa yuklanmoqda…';view.hidden=false;img.style.width=pdfZoom+'%';img.style.visibility='hidden';view.scrollTop=0;view.scrollLeft=0;const current=()=>request===pdfRequest&&active==='reader'&&currentBook===bid&&img===document.getElementById('pdf-image');const ok=()=>{if(!current())return;img.style.visibility='visible';msg.hidden=true;model.bookmarks[bid]=page;pdfReady=true;persist();};const fail=()=>{if(!current())return;pdfReady=false;msg.hidden=false;msg.textContent='Sahifa ochilmadi. Mutolaa sozlamalaridan qayta oching.';};img.onload=ok;img.onerror=fail;try{let src;if(bundled(bid)){src='books/'+bid+'/'+page+'.webp';}else{const data=REM.pdfPage(bid,page-1);if(typeof data!=='string'||!data.length||! /^[A-Za-z0-9+/=]+$/.test(data))throw Error('pdf');src='data:image/jpeg;base64,'+data;}img.src=src;if(img.complete&&img.naturalWidth>0)ok();}catch(e){fail();}}
  function quizMarkup(item,kind){const key=kind+'-'+item[0],q=kind==='audio'?item[4]:item[3],opts=kind==='audio'?item[5]:item[4];return `<div class="divider"></div><strong>${html(q)}</strong><div class="quiz-options">${opts.map((o,i)=>`<button class="secondary" data-act="quiz" data-id="${key}:${i}">${html(o)}</button>`).join('')}</div><p id="quiz-status" class="muted sm">${model.quiz[key]?'✓ Bu savolga to‘g‘ri javob bergansiz.':'Tinglab yoki tomosha qilib javob bering.'}</p>`;}
  function mediaMarkup(kind){const audio=kind==='audio',first=audio?32:40,items=imported(kind),legacy=Array.from({length:8},(_,i)=>first+i);let slot=audio?mediaSlot:videoSlot;let uri='';try{uri=String(REM?.mediaUri?.(slot)||'');}catch(e){}if(!uri&&items.length&&slot===first){slot=items[0];if(audio)mediaSlot=slot;else videoSlot=slot;uri=importedUri(slot);}if(!uri.startsWith('content://'))uri='';return `<section class="card"><h3>${audio?'Mening audiolarim':'Mening videolarim'}</h3><p class="muted sm">Telefoningizdagi qonuniy yuklangan ${audio?'MP3 / M4A':'MP4'} faylni tanlang. Fayl telefoningizda qoladi.</p><select id="${audio?'local-audio':'local-video'}">${[...items,...legacy].map(i=>`<option value="${i}" ${i===slot?'selected':''}>${html(model.mediaNames[i]||(i>=149?importedTitle(i):'Fayl '+(i-first+1)))}</option>`).join('')}</select><div class="row">${slot<48?`<button class="grow" data-act="media-pick" data-id="${slot}">＋ Fayl tanlash</button>`:`<span class="grow muted sm">Telegramdan saqlangan · offline</span>`}<button class="secondary" data-act="media-refresh">Yangilash</button></div><p><button class="secondary" data-act="media-name" data-id="${slot}">Nomini o‘zgartirish</button></p>${uri?`<${audio?'audio':'video'} id="study-player" src="${html(uri)}" controls playsinline preload="metadata"></${audio?'audio':'video'}><label class="label">Ijro tezligi</label><select id="playback-speed"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option></select>`:'<p class="muted">Fayl tanlang, keyin Yangilash tugmasini bosing.</p>'}<div class="row between"><span>Bugungi haqiqiy ijro</span><strong id="time-local-${slot}">${formatTime(total('content','local-'+slot))}</strong></div><p class="muted sm">Pauza va yuklanish vaqti ijro hisobiga kirmaydi. Fayl ijro etilmasa, Android fayl ruxsatini va formatini tekshiring.</p></section>`;}
  function renderListening(){const item=LESSONS.find(x=>x[0]===selectedAudio)||LESSONS[0];selectedAudio=item[0];return `<section class="card hero"><div class="eyebrow">REAL ENGLISH · A1–B1</div><h2>Tabiiy listening</h2><p>Robot ovozlar o‘rniga haqiqiy boshlovchilar va suhbatlar.</p></section><section class="card"><h3>BBC Learning English</h3><button data-act="source" data-id="5">Real Easy English · audio yuklamalar</button><p><button class="secondary" data-act="source" data-id="6">6 Minute English · audio yuklamalar</button></p><button class="secondary" data-act="source" data-id="10">Easy English · Apple Podcasts</button><p><button class="secondary" data-act="source" data-id="11">6 Minute English · Apple Podcasts</button></p><button class="secondary" data-act="source" data-id="2">British Council · A1 listening</button><p class="muted sm">Manbalar brauzerda ochiladi. Tashqarida tinglangan vaqt avtomatik hisoblanmaydi.</p><button class="secondary" data-act="manual-time" data-id="external-listening">Tashqi vaqtni kiritish</button></section>${mediaMarkup('audio')}${importInfo()}<section class="card"><h3>Original mashqlar · 8 ta</h3><p class="muted sm">Sun’iy audio olib tashlandi. Matnni o‘qing, ovoz chiqarib takrorlang va testni bajaring.</p><select id="audio-select">${LESSONS.map(x=>`<option value="${x[0]}" ${x[0]===item[0]?'selected':''}>${html(x[1])}</option>`).join('')}</select><p>${html(item[2])}</p><p class="muted">${html(item[3])}</p>${quizMarkup(item,'audio')}</section>`;}
  function renderCartoons(){const item=STORIES.find(x=>x[0]===selectedVideo)||STORIES[0];selectedVideo=item[0];return `<section class="card hero"><div class="eyebrow">WATCH · LISTEN · REPEAT</div><h2>Haqiqiy videolar</h2><p>Inglizcha suhbatlar, podkastlar va hikoyalar.</p></section><section class="card"><h3>Rasmiy video manbalari</h3><button data-act="source" data-id="7">BBC Learning English · YouTube</button><p><button class="secondary" data-act="source" data-id="8">Talking about routines · BBC</button></p><button class="secondary" data-act="source" data-id="9">Can apps teach you a language? · BBC</button><p><button class="secondary" data-act="source" data-id="3">British Council · animatsion hikoyalar</button></p><button class="secondary" data-act="source" data-id="4">VOA · Anna bilan ingliz tili</button><p class="muted sm">Videolar rasmiy manbada ochiladi. YouTube videolari APK ichiga ko‘chirilmagan.</p><button class="secondary" data-act="manual-time" data-id="external-video">Tashqi video vaqtini kiritish</button></section>${mediaMarkup('video')}${importInfo()}<section class="card"><h3>Original hikoyalar · 3 ta</h3><select id="video-select">${STORIES.map(x=>`<option value="${x[0]}" ${x[0]===item[0]?'selected':''}>${html(x[1])}</option>`).join('')}</select>${item[2].map(x=>`<p>${html(x[0])}</p>`).join('')}${quizMarkup(item,'video')}</section>`;}
  function renderUsage(){const period=usagePeriod,all=total('screen',null,period),rows=USAGE_KEYS.map(k=>[labels[k],total('screen',k,period),k]).sort((a,b)=>b[1]-a[1]);const items=[...catalogSlots.map(i=>[bookName(i),'book-'+i]),...Object.entries(model.customBooks).map(([i,n])=>[n,'book-'+i]),...imported('book').map(i=>[bookName(i),'book-'+i]),...imported('audio').concat(imported('video')).map(i=>[model.mediaNames[i]||importedTitle(i),'local-'+i]),...LESSONS.map(x=>[x[1],'audio-'+x[0]]),...STORIES.map(x=>[x[1],'video-'+x[0]]),['Tashqi mutolaa','external-reading'],['Tashqi listening','external-listening'],['Tashqi video','external-video'],...Array.from({length:16},(_,i)=>[model.mediaNames[32+i]||('Mahalliy '+(i<8?'audio ':'video ')+(i%8+1)),'local-'+(32+i)])];return `<section class="card hero"><div class="eyebrow">SHAXSIY ANALITIKA</div><h2 id="usage-total">${formatTime(all)}</h2><p>Ilova ekrani faol bo‘lgan vaqt</p><div class="row usage-period">${[1,7,30].map(n=>`<button class="${period===n?'':'secondary'} grow" data-act="period" data-id="${n}">${n===1?'Bugun':n+' kun'}</button>`).join('')}</div></section><section class="card"><h3>Bo‘limlar bo‘yicha vaqt</h3>${rows.map(([n,v,k])=>`<div class="usage-row"><div class="row between"><span>${html(n)}</span><strong id="usage-${k}">${formatTime(v)}</strong></div><div class="progress"><div id="bar-${k}" class="fill" style="width:${all?100*v/all:0}%"></div></div></div>`).join('')}<p class="muted sm">Telefon qulflanganda, ilova fon rejimiga o‘tganda yoki brauzer ochilganda avtomatik hisob to‘xtaydi. Ekran ochiq tursa, vaqt hisoblanadi.</p></section><section class="card"><h3>Ta’lim materiallari bo‘yicha</h3>${items.map(([n,k])=>[n,total('content',k,period),k]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]).map(([n,v,k])=>`<div class="row between item"><span>${html(n)}</span><strong id="time-${k}">${formatTime(v)}</strong></div>`).join('')||'<p class="muted">Hali yozilgan mutolaa, audio yoki video vaqti yo‘q.</p>'}<p class="muted sm">PDF ochiq ekrandagi vaqt, audio/video haqiqiy ijro vaqti va qo‘lda kiritilgan tashqi vaqt. Bular ilova ekran vaqtiga qo‘shib hisoblanmaydi.</p><button class="secondary" data-act="manual-time" data-id="external-reading">Tashqi mutolaa vaqtini kiritish</button></section>`;}
  function studyAction(action,ref){if(action==='books-download'){let ok=0;for(const i of catalogSlots)if(startBook(i))ok++;render();announce(ok?'Yuklashlar navbatga qo‘yildi.':'Yuklash boshlanmadi. Internetni tekshiring.');return true;}if(action==='pdf-download'){const ok=startBook(currentBook);showPdf();announce(ok?'Yuklash navbatga qo‘yildi.':'Yuklash boshlanmadi.');return true;}if(action==='media-pick'){flushUsage();try{if(!REM?.pickMedia?.(Number(ref)))throw Error();announce('Fayl tanlang, keyin Yangilash tugmasini bosing.');}catch(e){announce('Fayl tanlash Android ilovasida ishlaydi.');}return true;}if(action==='media-refresh'){flushUsage();render();return true;}if(action==='media-name'){const n=prompt('Fayl nomi',model.mediaNames[ref]||(Number(ref)>=149?importedTitle(ref):''));if(n?.trim()){model.mediaNames[ref]=safeString(n.trim(),100);persist();render();}return true;}if(action==='source'){openSource(Number(ref));return true;}if(action==='book-add'){const slot=Array.from({length:16},(_,i)=>i+16).find(i=>!model.customBooks[i]);if(slot===undefined){announce('32 ta PDF uchun joy mavjud.');return true;}const name=prompt('Kitob nomi');if(name?.trim()){model.customBooks[slot]=safeString(name.trim(),100);persist();currentBook=slot;pdfZoom=100;navigate('reader');}return true;}if(action==='book-open'){flushUsage();currentBook=Number(ref);if(!bundled(currentBook)&&(!Number.isInteger(currentBook)||currentBook<0||(currentBook>=32&&currentBook<48)||currentBook>=149))return true;pdfZoom=100;navigate('reader');if(catalogSlots.includes(currentBook)&&!pdfCount&&dlState(currentBook)===0){startBook(currentBook);showPdf();}return true;}if(action==='pdf-pick'){flushUsage();try{if(!REM?.pickPdf?.(currentBook))throw Error('picker');announce('PDF tanlang, so‘ng Ochish / yangilash tugmasini bosing.');}catch(e){announce('PDF tanlash Android ilovasida ishlaydi.');}return true;}if(action==='pdf-refresh'){showPdf();return true;}if(action==='pdf-prev'||action==='pdf-next'||action==='pdf-jump'){if(!pdfCount)return true;flushUsage();const target=action==='pdf-prev'?pdfRequestedPage-1:action==='pdf-next'?pdfRequestedPage+1:Number(document.getElementById('pdf-number').value);if(!Number.isInteger(target)||target<1||target>pdfCount){readerControls(pdfRequestedPage);if(action==='pdf-jump')announce('1–'+pdfCount+' oralig‘ida sahifa raqamini kiriting.');return true;}if(target!==pdfRequestedPage||!pdfReady)showPdf(target);return true;}if(['pdf-zoomout','pdf-zoomin','pdf-zoomreset'].includes(action)){pdfZoom=action==='pdf-zoomreset'?100:Math.min(250,Math.max(100,pdfZoom+(action==='pdf-zoomin'?25:-25)));const im=document.getElementById('pdf-image');if(im)im.style.width=pdfZoom+'%';readerControls(pdfRequestedPage);return true;}if(action==='period'){usagePeriod=[1,7,30].includes(+ref)?+ref:7;flushUsage();render();return true;}if(action==='manual-time'){if(!contentKeys().includes(ref))return true;const raw=prompt('Sarflagan vaqtingizni HH:MM:SS shaklida kiriting. Masalan 00:12:35');if(raw===null)return true;const m=/^(\d{1,2}):([0-5]\d):([0-5]\d)$/.exec(raw.trim());const n=m?Number(m[1])*3600+Number(m[2])*60+Number(m[3]):0;if(n<1||n>43200){announce('00:00:01–12:00:00 orasida vaqt kiriting.');return true;}addUsage('content',ref,n);persist();if(active==='usage'||active==='reader')render();announce('Vaqt saqlandi.');return true;}if(action==='quiz'){const [key,index]=String(ref).split(':');const isAudio=key.startsWith('audio-'),item=(isAudio?LESSONS:STORIES).find(x=>key===(isAudio?'audio-':'video-')+x[0]);if(!item)return true;const correct=Number(index)===(isAudio?item[6]:item[5]);if(correct){model.quiz[key]=true;persist();}const status=document.getElementById('quiz-status');if(status)status.textContent=correct?'✓ To‘g‘ri! Barakalla.':'Yana tinglang va urinib ko‘ring.';return true;}return false;}

  let model,storageOK=true,active='home',timer=null,toastTimer=null,recovery='',storageBlocked=false;
  try{const raw=localStorage.getItem(STORAGE_KEY);if(raw){try{model=normalize(JSON.parse(raw))}catch(e){const mirror=localStorage.getItem(STORAGE_KEY+'-previous');if(mirror){storageBlocked=true;model=normalize(JSON.parse(mirror));storageBlocked=false;recovery='Oldingi saqlangan nusxa tiklandi.';}else{storageBlocked=true;throw e;}}}else model=fresh()}catch(e){model=fresh();storageOK=false;recovery='Saqlangan ma’lumotni o‘qib bo‘lmadi. Zaxiradan tiklash uchun Sozlamalarga kiring.';}
  timer=model.focusTimer;
  function persist(){try{model.focusTimer=timer;if(storageBlocked)throw Error('recovery required');const data=JSON.stringify(model),old=localStorage.getItem(STORAGE_KEY);if(old!==data){if(old&&!recovery){try{JSON.parse(old);localStorage.setItem(STORAGE_KEY+'-previous',old)}catch(e){}}localStorage.setItem(STORAGE_KEY,data);}storageOK=true;}catch(e){storageOK=false;announce('Ma’lumot saqlanmadi: zaxira nusxasi yarating.')}}
  function day(k){if(!model.days[k]){model.days[k]={target:model.habits.map(h=>h.id),done:[],water:0,focus:0,minutes:0,note:'',mood:'Yaxshi'};persist();}return model.days[k]}
  function today(){return day(dateKey())}
  function percentage(d){if(!d||!Array.isArray(d.target)||d.target.length===0)return 0;return Math.round(100*d.done.filter(x=>d.target.includes(x)).length/d.target.length)}
  function streak(){let n=0,i=0; if(percentage(model.days[dateShift(0)])!==100)i=-1;while(percentage(model.days[dateShift(i)])===100&&n<2000){n++;i--;}return n}
  function xp(){return Object.values(model.days).reduce((t,d)=>t+(Array.isArray(d.done)?d.done.length:0)*20+(Number(d.focus)||0)*30,0)}
  function change(fn){fn();persist();render()}
  function announce(msg){const box=document.getElementById('toast');if(!box)return;box.textContent=msg;box.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('visible'),2800)}
  const profileName=()=>model.profile.name;
  const greeting=()=>{const h=new Date().getHours();return h<5?'Xayrli tun':h<12?'Xayrli tong':h<18?'Xayrli kun':'Xayrli kech'};
  const personal=(message)=>profileName()?`${profileName()}, ${message}`:message;
  function profileCard(){return `<section class="card profile-card"><div class="row"><div class="avatar">${html((profileName()||'I').slice(0,1).toUpperCase())}</div><div class="grow"><div class="eyebrow">SHAXSIY PROFIL</div><h3>${html(profileName()?greeting()+', '+profileName()+'!':'Xush kelibsiz!')}</h3><p class="muted sm">${profileName()?'Bugun ham maqsadlaringiz sari qadam tashlang.':'Sizga qanday murojaat qilishimizni belgilang.'}</p></div></div><button class="secondary" data-tab="profile">${profileName()?'Profilni tahrirlash':'Profil yaratish'}</button></section>`}
  function renderProfile(){return `<section class="card profile-card"><div class="eyebrow">INTIZOM PRO · 7.3</div><h2>${profileName()?'Profilim':'Xush kelibsiz!'}</h2><p class="muted">Ilova ismingizni eslab qoladi va sizga shaxsiy tarzda murojaat qiladi.</p><form id="profile-form"><label class="label" for="profile-name">Ismingiz yoki taxallusingiz</label><input id="profile-name" required maxlength="50" autocomplete="given-name" value="${html(profileName())}" placeholder="Masalan, Bexruzbek"><label class="label" for="profile-style">Murojaat uslubi</label><select id="profile-style"><option value="formal" ${model.profile.style==='formal'?'selected':''}>Hurmat bilan (siz)</option><option value="friendly" ${model.profile.style==='friendly'?'selected':''}>Do‘stona (sen)</option></select><p><button type="submit">${profileName()?'Saqlash':'Boshlash'}</button></p></form><p class="muted sm">Profil faqat shu qurilmada saqlanadi. Bu parol bilan himoyalangan akkaunt emas. Internet yoki telefon raqami talab qilinmaydi.</p></section>`}
  const checked=(d,id)=>d.done.includes(id);
  function habitList(edit=false){const d=today();if(!model.habits.length)return '<p class="empty">Odat mavjud emas. Birinchi odatingizni qo‘shing.</p>';
    return model.habits.map(h=>`<div class="item"><input type="checkbox" aria-label="${html(h.name)}" data-act="toggle-habit" data-id="${html(h.id)}" ${checked(d,h.id)?'checked':''}><div class="grow"><p class="${checked(d,h.id)?'done':''}">${html(h.name)}</p><small>${html(h.cat)}</small></div>${edit?`<button class="secondary edit-btn" data-act="habit-edit" data-id="${html(h.id)}" aria-label="Tahrirlash">✎</button><button class="danger" data-act="delete-habit" data-id="${html(h.id)}" aria-label="O‘chirish">×</button>`:''}</div>`).join('')}
  function renderHome(){const d=today(),p=percentage(d),score=xp();return `${profileCard()}<section class="card"><div class="row between"><h2 class="sectiontitle">Ta’lim va mutolaa</h2><button class="secondary" data-tab="learn">Ochish →</button></div><p class="muted sm">Kitoblar · Listening · Multfilmlar · Vaqt tahlili</p></section><section class="card hero"><div class="eyebrow">${html(dateKey())} · Bugungi yutuq</div><h2>${p}%</h2><div class="progress"><div class="fill" style="width:${p}%"></div></div><p>${d.done.length}/${d.target.length} odat bajarildi</p><div class="stats"><div class="stat"><strong>${score}</strong><small>XP ball</small></div><div class="stat"><strong>${streak()}</strong><small>Ketma-ket kun</small></div><div class="stat"><strong>${Math.floor(score/100)+1}</strong><small>Daraja</small></div></div></section><section class="card"><div class="row between"><h2 class="sectiontitle">Bugungi odatlar</h2><span class="badge">+20 XP / odat</span></div>${habitList()}</section><section class="card"><div class="row between"><h2 class="sectiontitle">Suv nazorati</h2><strong>${d.water} stakan</strong></div><div class="row"><button class="secondary" data-act="water-down" aria-label="Bir stakan kamaytirish">−</button><div class="progress grow"><div class="fill" style="width:${Math.min(100,100*d.water/model.waterGoal)}%"></div></div><button data-act="water-up" aria-label="Bir stakan qo‘shish">+</button></div><p class="muted sm">Kunlik shaxsiy maqsad: ${model.waterGoal} stakan. Sozlamalarda o‘zgartiring.</p></section><section class="tip">${html(personal(model.profile.style==='friendly'?(p===100?'barakalla! Bugungi rejangni yakunlading.':p>=50?'yaxshi ketyapsan! Navbatdagi vazifani tanla.':'bugun bitta kichik vazifadan boshla.'):(p===100?'barakalla! Bugungi rejangizni yakunladingiz.':p>=50?'yaxshi davom etyapsiz. Navbatdagi vazifani tanlang.':'bugun bitta kichik vazifadan boshlang.')))}</section>`;}
  function renderHabits(){return `<section class="card"><h2 class="sectiontitle">Odatlarim</h2><p class="muted sm">Odatni o‘chirishingiz tarixiy statistikani o‘zgartirmaydi.</p>${habitList(true)}<form id="habit-form"><label class="label" for="habit-name">Yangi odat</label><input required maxlength="120" id="habit-name" placeholder="Masalan, har kuni 10 ta yangi so‘z"><div class="formrow"><select id="habit-cat" aria-label="Toifa"><option>Intizom</option><option>Ta’lim</option><option>Salomatlik</option><option>Ish</option><option>Boshqa</option></select><button>+ Qo‘shish</button></div></form></section>`}
  function remaining(){return timer?(timer.end?Math.max(0,timer.end-Date.now()):timer.left):model.duration*60000}
  function renderFocus(){const d=today(),r=Math.ceil(remaining()/1000);return `<section class="card"><h2 class="sectiontitle">Chuqur fokus</h2><p class="muted">Telefonni chetga qo‘ying va bitta vazifani bajaring.</p><label class="label" for="duration">Seans davomiyligi</label><select id="duration" ${timer?'disabled':''}>${[5,15,25,50,90].map(n=>`<option value="${n}" ${model.duration===n?'selected':''}>${n} daqiqa</option>`).join('')}</select><div class="clock" id="clock">${String(Math.floor(r/60)).padStart(2,'0')}:${String(r%60).padStart(2,'0')}</div><div class="row"><button class="grow" data-act="timer-toggle">${timer?.end?'Pauza':timer?'Davom ettirish':'Boshlash'}</button><button class="secondary" data-act="timer-reset">Qayta</button></div><p class="muted sm">Taymer vaqti saqlanadi; ilovani qayta ochsangiz davom etadi. Ilova yopiq holatda fokus tugaganligi haqida bildirishnoma yuborilmaydi.</p></section><section class="card"><h2 class="sectiontitle">Bugungi fokus natijasi</h2><div class="stats"><div class="stat"><strong>${d.focus}</strong><small>Seans</small></div><div class="stat"><strong>${d.minutes}</strong><small>Daqiqa</small></div><div class="stat"><strong>${d.focus*30}</strong><small>XP</small></div></div></section>`}
  function renderGoals(){return `<section class="card"><h2 class="sectiontitle">Shaxsiy maqsadlar</h2><p class="muted sm">${model.goals.filter(g=>g.done).length}/${model.goals.length} bajarildi</p>${model.goals.length?model.goals.map(g=>`<div class="item"><input type="checkbox" data-act="goal-toggle" data-id="${html(g.id)}" aria-label="Maqsad bajarildi" ${g.done?'checked':''}><div class="grow"><p class="${g.done?'done':''}">${html(g.name)}</p><small>${html(g.due||'Muddat belgilanmagan')}${!g.done&&g.due&&g.due<dateKey()?' · Muddati o‘tgan':''}</small></div><button class="secondary edit-btn" data-act="goal-edit" data-id="${html(g.id)}" aria-label="Tahrirlash">✎</button><button class="danger" data-act="goal-delete" data-id="${html(g.id)}" aria-label="O‘chirish">×</button></div>`).join(''):'<p class="empty">Maqsad qo‘shing va unga erishish jarayonini kuzating.</p>'}<form id="goal-form"><label class="label">Maqsad nomi</label><input required maxlength="240" name="goal" placeholder="Masalan, IELTS 7.2 ga erishish"><label class="label">Muddat (ixtiyoriy)</label><div class="formrow"><input type="date" name="due"><button>+ Qo‘shish</button></div></form></section>`}
  function renderStats(){let lines='',count=0;for(let i=-6;i<=0;i++){const k=dateShift(i),p=percentage(model.days[k]);count+=p;lines+=`<div class="meter"><span>${k.slice(5)}</span><div class="progress"><div class="fill" style="width:${p}%"></div></div><b>${p}%</b></div>`}const d=today();return `<section class="card"><h2 class="sectiontitle">7 kunlik tahlil</h2>${lines}<div class="divider"></div><div class="row between"><span class="muted">O‘rtacha bajarish</span><strong>${Math.round(count/7)}%</strong></div><div class="row between"><span class="muted">Jami XP ball</span><strong>${xp()}</strong></div><div class="row between"><span class="muted">Ketma-ket mukammal kun</span><strong>${streak()}</strong></div></section><section class="card"><h2 class="sectiontitle">Kechki kundalik</h2><label class="label" for="mood">Bugungi kayfiyat</label><select id="mood">${['Ajoyib','Yaxshi','Qiyin'].map(m=>`<option ${m===d.mood?'selected':''}>${m}</option>`).join('')}</select><label class="label" for="journal">Bugungi xulosa</label><textarea id="journal" rows="5" maxlength="4000" placeholder="Bugun nimani o‘rgandim? Ertaga nimani yaxshilayman?">${html(d.note)}</textarea><p class="muted sm">Yozilgan matn avtomatik saqlanadi.</p></section>`}
  function renderPlan(){const plans=model.plans.slice().sort((a,b)=>a.time.localeCompare(b.time));const done=Object.entries(model.days).filter(([k,v])=>model.challenge&&k>=model.challenge.start&&k<plusDays(model.challenge.start,model.challenge.length)&&k<=dateKey()&&percentage(v)===100).length;return `<section class="card"><h2 class="sectiontitle">Kun tartibi</h2>${plans.length?plans.map(p=>`<div class="item"><input type="checkbox" data-act="plan-toggle" data-id="${html(p.id)}" aria-label="Reja bajarildi" ${p.completed===dateKey()?'checked':''}><div class="grow"><p class="${p.completed===dateKey()?'done':''}">${html(p.time)} · ${html(p.name)}</p></div><button class="secondary edit-btn" data-act="plan-edit" data-id="${html(p.id)}" aria-label="Tahrirlash">✎</button><button class="danger" data-act="plan-delete" data-id="${html(p.id)}" aria-label="O‘chirish">×</button></div>`).join(''):'<p class="empty">Vaqt bo‘yicha reja tuzing.</p>'}<form id="plan-form"><label class="label">Vaqt va vazifa</label><div class="formrow three"><input type="time" required name="time" value="08:00"><input required maxlength="120" name="plan" placeholder="Nima qilasiz?"><button>+</button></div></form></section><section class="card"><h2 class="sectiontitle">Intizom marafoni</h2>${model.challenge?`<p>${model.challenge.length} kunlik marafon · Boshlanish: ${html(model.challenge.start)}</p><strong>${done}/${model.challenge.length} mukammal kun</strong><div class="progress"><div class="fill" style="width:${100*done/model.challenge.length}%"></div></div><p class="muted sm">${dateKey()>=plusDays(model.challenge.start,model.challenge.length)?'Marafon muddati tugadi.':'Yakun: '+plusDays(model.challenge.start,model.challenge.length-1)}</p><p><button class="secondary" data-act="challenge-stop">Marafonni tugatish</button></p>`:`<p class="muted">Uzluksiz odatlar shakllantirish uchun muddat tanlang.</p><div class="formrow"><select id="challenge-length">${[21,30,66,90].map(x=>`<option value="${x}">${x} kun</option>`).join('')}</select><button data-act="challenge-start">Boshlash</button></div>`}</section><section class="card"><h2 class="sectiontitle">Shaxsiy murabbiy</h2><div class="tip">${percentage(today())===100?'Bugun o‘zingizga bergan va’dani bajardingiz. Ertangi maqsadni ham yozing.':percentage(today())>=50?'Kuningizning qolgan qismi uchun birinchi navbatda eng kichik qolgan vazifani bajaring.':'Hozir atigi 5 daqiqa ishlang. Katta yutuqlar shunday boshlanadi.'}</div><p class="muted sm">Bu internetga ulanmaydigan, qoidalarga asoslangan tavsiya; AI xizmati emas.</p></section>`}
  function nextAlarm(time){const [h,m]=time.split(':').map(Number),d=new Date();d.setHours(h,m,0,0);if(d.getTime()<=Date.now())d.setDate(d.getDate()+1);return d.getTime()}
  function syncReminder(r){if(!REM)return false;try{if(!r.on){REM.removeReminder(r.slot);return true}return !!REM.setReminder(r.slot,nextAlarm(r.time),personal(model.profile.style==='friendly'?r.name+' — vaqti keldi!':r.name+' — rejangizni bajaring!'))}catch(e){return false}}
  function syncAllReminders(){if(!REM)return;for(let i=0;i<32;i++){const r=model.reminders.find(x=>x.slot===i);try{if(r?.on)syncReminder(r);else REM.removeReminder(i)}catch(e){}}}
  function renderReminders(){return `<section class="card hero"><div class="eyebrow">ESLATMALAR MARKAZI</div><h2>${model.reminders.filter(r=>r.on).length}</h2><p>Faol kunlik eslatmalar</p><button data-act="reminder-test">Test bildirishnomasi</button><p><button class="secondary" data-act="reminder-status">Ruxsatlarni tekshirish</button></p><p><button class="secondary" data-act="reminder-permission">Bildirishnoma ruxsatini so‘rash</button></p><p><button class="secondary" data-act="exact-permission">Aniq eslatma sozlamalari</button></p><p id="reminder-diagnostic" class="muted sm"></p></section><section class="card"><h2 class="sectiontitle">Kunlik eslatmalar</h2><p class="muted sm">Vaqtni o‘zgartiring va kerakli eslatmani yoqing. Telefon sozlamalarida bildirishnomaga ruxsat bering. Android batareya rejimi vaqtdan kechikishga sabab bo‘lishi mumkin.</p>${model.reminders.slice().sort((a,b)=>a.time.localeCompare(b.time)).map(r=>`<div class="reminder-row"><div class="row between"><label class="row"><input type="checkbox" data-act="reminder-toggle" data-id="${r.slot}" ${r.on?'checked':''}> <strong>${html(r.name)}</strong></label><button class="danger" data-act="reminder-delete" data-id="${r.slot}" aria-label="O‘chirish">×</button></div><div class="row"><input class="grow" type="time" data-act="reminder-time" data-id="${r.slot}" value="${html(r.time)}"><span class="badge">${r.on?'Faol':'O‘chiq'}</span></div></div>`).join('')}<form id="reminder-form"><label class="label">Shaxsiy eslatma</label><input name="name" required maxlength="100" placeholder="Masalan, suv ichish"><div class="formrow"><input name="time" type="time" required value="12:00"><button>+ Qo‘shish</button></div></form><p class="muted sm">32 tagacha kunlik eslatma. Qayta yoqilganda tizim eslatmalarni tiklashga urinadi. Majburan to‘xtatilgan ilovani qayta oching.</p></section>`}
  // Offline smart supervision: local, transparent rules; not a cloud language model.
  // Offline, explainable recommendations using only locally stored data.
  function smartReport(now=new Date()){
    const d=today(),p=percentage(d),key=dateKey(now),left=model.habits.filter(h=>d.target.includes(h.id)&&!d.done.includes(h.id));
    const goals=model.goals.filter(g=>!g.done);
    const overdue=goals.filter(g=>validDate(g.due)&&g.due<key),due=goals.filter(g=>validDate(g.due)&&g.due===key);
    const plans=model.plans.filter(x=>x.completed!==key),clock=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}`;
    const late=plans.filter(x=>validTime(x.time)&&x.time<clock),upcoming=plans.filter(x=>validTime(x.time)&&x.time>=clock).sort((a,b)=>a.time.localeCompare(b.time));
    const hist=Array.from({length:7},(_,i)=>model.days[dateShift(i-6)]).filter(Boolean);
    const average=hist.length?Math.round(hist.reduce((a,b)=>a+percentage(b),0)/hist.length):0;
    const previous=Array.from({length:7},(_,i)=>model.days[dateShift(i-13)]).filter(Boolean);
    const prevAvg=previous.length?Math.round(previous.reduce((a,b)=>a+percentage(b),0)/previous.length):null;
    const trend=prevAvg===null?null:average-prevAvg;
    const focusToday=Number(d.focus)||0;
    const readingToday=total('content',null,1);
    const tips=[],push=(level,title,detail,tab)=>tips.push({level,title,detail,tab});
    if(overdue.length)push('warning','Muddati o‘tgan maqsadlar',`${overdue.length} ta maqsad muddati o‘tgan. Eng yaqin maqsadni qayta rejalang: ${overdue[0].name}.`,'goals');
    if(late.length)push('warning','Kechikkan kun tartibi',`${late.length} ta vazifa belgilanmagan. Avval ${late[0].name} ishini bajaring yoki vaqtini yangilang.`,'plan');
    if(due.length)push('today','Bugungi muddat',`${due.length} ta maqsad bugun yakunlanishi kerak: ${due[0].name}.`,'goals');
    if(left.length){const education=left.find(h=>/ta.lim|ingliz|kitob|o.qish/i.test(h.cat+' '+h.name));const first=late.length?null:(education||left[0]);if(first)push('today','Hozirgi eng yaxshi qadam',`${first.name}: boshlash uchun 5–10 daqiqa ajrating. Tugagach Odatlar bo‘limida belgilang.`,'habits');}
    if(upcoming.length)push('today','Keyingi rejalashtirilgan ish',`${upcoming[0].time} — ${upcoming[0].name}. Vaqti yetguncha kerakli narsalarni tayyorlang.`,'plan');
    if(trend!==null&&trend<=-15)push('warning','Haftalik pasayish',`Bajarish ko‘rsatkichi avvalgi haftaga nisbatan ${Math.abs(trend)} punkt pasaygan. Ertaga vazifalarni kamaytirib, eng muhim ikkitasidan boshlang.`,'stats');
    else if(trend!==null&&trend>=15)push('good','Haftalik o‘sish',`O‘rtacha natijangiz ${trend} punkt yaxshilangan. Shu jadvalni davom ettiring.`,'stats');
    if(model.habits.length&&p<50&&now.getHours()>=18)push('warning','Kechki tekshiruv',`Bugungi odatlar ${p}% bajarilgan. Uxlashdan oldin bitta kichik vazifani yakunlang.`,'habits');
    if(!focusToday&&now.getHours()>=10&&now.getHours()<21)push('today','Fokus mashg‘uloti',`Bugun fokus sessiyasi qayd etilmagan. 5 yoki 25 daqiqalik chalg‘imasdan ishlashni sinang.`,'focus');
    if(readingToday<600&&now.getHours()>=17)push('today','Mutolaa va ta’lim',`Bugun ilova ichidagi mutolaa/ta’lim vaqti 10 daqiqadan kam qayd etilgan. Kitobdan 5 sahifa o‘qing.`,'learn');
    if(!left.length&&model.habits.length)push('good','Bugungi reja bajarildi',`Barcha ${d.target.length} odat bajarildi! Ertangi kunning uchta muhim vazifasini belgilang.`,'plan');
    if(!hist.length)push('today','Tahlilni boshlash',`Hozircha tarix kam. Odatlarni har kuni belgilasangiz, haftalik o‘sish va tavsiyalar aniqroq bo‘ladi.`,'habits');
    const priority=tips.find(t=>t.level==='warning')||tips.find(t=>t.level==='today')||tips[0];
    return {p,average,trend,late:late.length,overdue:overdue.length,remaining:left.length,focusToday,readingToday,tips,priority,trackedDays:hist.length};
  }
  function renderMonitor(){const r=smartReport(),badge=r.trend===null?'Ma’lumot yig‘ilmoqda':r.trend>=0?'+'+r.trend+' punkt':r.trend+' punkt';return `<section class="card hero"><div class="eyebrow">OFFLINE AQLLI NAZORAT · 7.6</div><h2>${r.p}%</h2><p>Bugungi odatlar · ${r.remaining} ta bajarilmagan</p><div class="stats"><div class="stat"><strong>${r.average}%</strong><small>7 kun o‘rtacha</small></div><div class="stat"><strong>${r.late}</strong><small>Kechikkan reja</small></div><div class="stat"><strong>${r.overdue}</strong><small>Kechikkan maqsad</small></div></div></section><section class="card"><h2>Bugungi ustuvor vazifa</h2>${r.priority?`<strong>${html(r.priority.title)}</strong><p>${html(r.priority.detail)}</p><button data-tab="${r.priority.tab}">Bajarishga o‘tish →</button>`:'<p>Bugun uchun barcha vazifalar bajarilgan.</p>'}</section><section class="card"><h2>Haftalik natija va vaqt</h2><div class="item row between"><span>O‘tgan haftaga nisbatan</span><strong>${html(badge)}</strong></div><div class="item row between"><span>Fokus sessiyalari</span><strong>${r.focusToday} ta</strong></div><div class="item row between"><span>Mutolaa va ta’lim</span><strong>${formatTime(r.readingToday)}</strong></div><p class="muted sm">Tavsiyalar faqat ilovada qayd etilgan faoliyatga asoslanadi. Telefonning barcha ishlatilgan vaqtini kuzatmaydi.</p></section><section class="card"><h2>Shaxsiy tavsiyalar</h2>${r.tips.map(t=>`<div class="item"><div class="grow"><strong>${t.level==='warning'?'⚠ ':t.level==='good'?'✓ ':'• '}${html(t.title)}</strong><p class="muted sm">${html(t.detail)}</p><button class="secondary" data-tab="${t.tab}">Bo‘limni ochish</button></div></div>`).join('')}<p class="muted sm">Internet talab qilmaydigan qoidalarga asoslangan yordamchi. Bu bulutli generativ AI emas. Tavsiyalar qurilmadagi saqlangan yozuvlardan tuziladi.</p></section><section class="card"><h3>Tezkor harakatlar</h3><div class="row"><button class="secondary grow" data-tab="habits">✓ Odatlar</button><button class="secondary grow" data-tab="focus">◷ Fokus</button><button class="secondary grow" data-tab="learn">▤ Kitoblar</button></div><p><button data-tab="reminders">🔔 Eslatmalar</button></p></section>`;}
  function renderSettings(){return `<section class="card"><h2 class="sectiontitle">Sozlamalar</h2><button class="secondary" data-tab="monitor">🧠 Aqlli nazorat</button><p><button class="secondary" data-tab="profile">Shaxsiy profil</button></p><label class="label" for="appearance">Ko‘rinish</label><select id="appearance"><option value="dark" ${model.appearance==='dark'?'selected':''}>Tungi rejim</option><option value="light" ${model.appearance==='light'?'selected':''}>Kunduzgi rejim</option></select><label class="label" for="water-goal">Suv maqsadi (stakan)</label><input type="number" min="1" max="20" id="water-goal" value="${model.waterGoal}"><div class="divider"></div><button data-tab="reminders">🔔 Eslatmalarni boshqarish</button><div class="divider"></div><h3>Zaxira va tiklash</h3><p class="muted sm">Ma’lumotlar telefonda saqlanadi. Telefon almashtirish yoki ilovani o‘chirishdan oldin zaxira oling. Zaxira matnini nusxalab xavfsiz joyda saqlang; u shifrlanmagan.</p><button data-act="backup">Zaxira matnini ko‘rsatish</button><p><button data-act="restore-text">Zaxirani matndan tiklash</button></p><textarea id="backup-text" rows="5" placeholder="Zaxira matni shu yerda"></textarea><div class="divider"></div><h3>🔐 Kirish himoyasi</h3><p class="muted sm">Ilova har safar ochilganda PIN-kod so‘raydi. 4–8 raqamli kodni istalgan vaqtda o‘zgartirishingiz mumkin.</p><button class="secondary" type="button" id="pin-manage">🔐 PIN-kodni boshqarish</button><p class="muted sm" id="pin-state">Himoya holati tekshirilmoqda...</p><div class="divider"></div><h3>Ma’lumot xavfsizligi</h3><p class="muted sm">Kitob yuklash internetdan foydalanadi. Shaxsiy yozuvlar mahalliy xotirada saqlanadi; tashqi manbalar brauzerda ochiladi. PDF fayllari zaxira matniga kirmaydi, ular telefoningizda qoladi. Barcha yozuvlar mahalliy xotirada. Ilova ma’lumotlari o‘chirilsa, ular ham yo‘qoladi.</p><p class="muted sm">${storageOK?'✓ Oxirgi saqlash muvaffaqiyatli':'⚠ Ma’lumotni saqlashda muammo yuz berdi'}</p></section>`}
  const tabs=[['home','⌂','Asosiy'],['habits','✓','Odatlar'],['focus','◷','Fokus'],['reminders','🔔','Eslatma'],['learn','▤','Ta’lim'],['more','☷','Boshqa']];
  const subpages=new Set(['pricing','subscription','ai-chat','admin-demo','monitor','profile','goals','plan','stats','settings','library','reader','listening','cartoons','usage']);
  const labels={pricing:'Tariflar va narxlar',subscription:'Mening obunam','ai-chat':'AI murabbiy', 'admin-demo':'Admin demo',monitor:'Aqlli nazorat',home:'Asosiy',habits:'Odatlar',focus:'Fokus',reminders:'Eslatma',more:'Boshqaruv markazi',profile:'Shaxsiy profil',goals:'Shaxsiy maqsadlar',plan:'Kun tartibi va marafon',stats:'Statistika va kundalik',settings:'Sozlamalar va zaxira',learn:'Ta’lim',library:'PDF kutubxona',reader:'PDF mutolaa',listening:'Listening',cartoons:'Multfilmlar',usage:'Vaqt tahlili'};
  let navStack=[];
  function scrollTop(){window.scrollTo({top:0,behavior:'instant'});}
  function navigate(next,root=false){if(!Object.hasOwn(labels,next)||next===active)return;flushUsage();pdfReady=false;if(root){navStack=next==='home'?[]:['home'];}else{navStack.push(active);}active=next;render();scrollTop();}
  function back(){if(active==='home')return;flushUsage();pdfReady=false;active=navStack.pop()||(subpages.has(active)?'more':'home');render();scrollTop();}
  window.IntizomBack=()=>{if(window.IntizomPin?.isLocked?.())return;if(active!=='home'){back();return;}flushUsage();try{REM?.closeApp()}catch(e){}};
  function renderBack(){const bar=document.getElementById('backbar');bar.hidden=active==='home';if(bar.hidden){bar.innerHTML='';return;}const prev=navStack.at(-1)||(subpages.has(active)?'more':'home');bar.innerHTML=`<button type="button" data-act="nav-back" aria-label="Ortga, ${html(labels[prev])}"><span aria-hidden="true">&#8592;</span> Ortga</button><span class="back-title">${html(labels[active])}</span>`;}
  function render(){renderBack();const nav=document.getElementById('nav');nav.className='tabs';nav.innerHTML=tabs.map(([k,ic,t])=>`<button data-tab="${k}" class="${(active===k||(k==='more'&&subpages.has(active)&&!['library','reader','listening','cartoons','usage'].includes(active))||(k==='learn'&&['library','reader','listening','cartoons','usage'].includes(active)))?'active':''}" ${(active===k||(k==='more'&&subpages.has(active)&&!['library','reader','listening','cartoons','usage'].includes(active))||(k==='learn'&&['library','reader','listening','cartoons','usage'].includes(active)))?'aria-current="page"':''}><b>${ic}</b><span>${t}</span></button>`).join('');const a=document.getElementById('app');document.body.classList.toggle('light',model.appearance==='light');document.body.classList.toggle('reader-mode',active==='reader');a.innerHTML=['pricing','subscription','ai-chat','admin-demo'].includes(active)?window.IntizomSubscriptions.render(active):active==='monitor'?renderMonitor():active==='profile'?renderProfile():active==='home'?renderHome():active==='habits'?renderHabits():active==='focus'?renderFocus():active==='goals'?renderGoals():active==='stats'?renderStats():active==='plan'?renderPlan():active==='settings'?renderSettings():active==='reminders'?renderReminders():active==='learn'?renderLearn():active==='library'?renderLibrary():active==='reader'?renderReader():active==='listening'?renderListening():active==='cartoons'?renderCartoons():active==='usage'?renderUsage():`<section class="card"><h2 class="sectiontitle">Boshqaruv markazi</h2><div class="item"><button class="secondary grow" data-tab="pricing">💳 Tariflar va narxlar</button></div><div class="item"><button class="secondary grow" data-tab="subscription">👤 Mening obunam</button></div><div class="item"><button class="secondary grow" data-tab="ai-chat">✨ AI murabbiy</button></div><div class="item"><button class="secondary grow" data-tab="admin-demo">📊 Admin panel (demo)</button></div><div class="item"><button class="secondary grow" data-tab="monitor">🧠 Offline aqlli nazorat</button></div><div class="item"><button class="secondary grow" data-tab="profile">♙ Shaxsiy profil</button></div><div class="item"><button class="secondary grow" data-tab="goals">◎ Shaxsiy maqsadlar</button></div><div class="item"><button class="secondary grow" data-tab="plan">🗓 Kun tartibi va marafon</button></div><div class="item"><button class="secondary grow" data-tab="stats">▥ Statistika va kundalik</button></div><div class="item"><button class="secondary grow" data-tab="settings">⚙ Sozlamalar va zaxira</button></div><div class="item"><button class="secondary grow" data-tab="usage">◷ Vaqt tahlili</button></div></section>`;a.insertAdjacentHTML('afterbegin',`<div class="liveclock"><span>● ${html(labels[active])} · bugun</span><strong id="live-time">${formatTime(total('screen',active))}</strong></div>`);updateClock();if(active==='reader')showPdf();const player=document.getElementById('study-player');if(player){const slot=active==='listening'?mediaSlot:videoSlot;player.addEventListener('loadedmetadata',()=>{const at=Number(model.mediaPositions[slot])||0;if(at>0&&at<player.duration-1)player.currentTime=at;},{once:true});player.addEventListener('pause',()=>{if(Number.isFinite(player.currentTime))model.mediaPositions[slot]=player.ended?0:player.currentTime;persist();});player.addEventListener('ended',()=>{model.mediaPositions[slot]=0;persist();});player.addEventListener('play',()=>{mediaLast={player,pos:player.currentTime};mediaCarry=0;});player.addEventListener('seeking',()=>{mediaLast=null;mediaCarry=0;});player.addEventListener('error',()=>announce('Media ochilmadi. Boshqa MP3 yoki MP4 faylni tanlang.'));}}
  function updateClock(){if(timer&&timer.end&&timer.end<=Date.now()){const duration=timer.duration,k=dateKey(new Date(timer.end));timer=null;const d=day(k);d.focus+=1;d.minutes+=duration;persist();if(active==='home'||active==='focus')render();announce(personal('fokus seansi yakunlandi! +30 XP'));if(navigator.vibrate)navigator.vibrate([170,90,170]);}const el=document.getElementById('clock');if(el){let seconds=Math.ceil(remaining()/1000);el.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}}
  function exportBackup(){const el=document.getElementById("backup-text");el.value=JSON.stringify(model);el.focus();el.select();announce("Zaxira matnini nusxalang");}
  async function importBackup(file){if(!file)return;try{if(file.size>2500000)throw Error('Too large');const data=normalize(JSON.parse(await file.text()));if(!confirm('Zaxira tiklansa, barcha joriy ma’lumotlar almashtiriladi. Davom etilsinmi?'))return;const before=model,oldTimer=timer,wasBlocked=storageBlocked;model=data;timer=model.focusTimer;storageBlocked=false;recovery='';persist();if(!storageOK){model=before;timer=oldTimer;storageBlocked=wasBlocked;throw Error('Storage failure');}syncAllReminders();render();announce('Zaxira muvaffaqiyatli tiklandi');}catch(e){announce('Zaxira fayli noto‘g‘ri yoki juda katta.')}}
  const find=(array,id)=>array.find(x=>String(x.id)===id);
  document.addEventListener('click',e=>{
    const tab=e.target.closest('[data-tab]');if(tab){navigate(tab.dataset.tab,!!tab.closest('#nav'));return}
    const b=e.target.closest('button[data-act]');if(!b)return;const action=b.dataset.act;if(action==='nav-back'){back();return;}const ref=b.dataset.id;if(studyAction(action,ref))return;const d=today();
    if(['habit-edit','goal-edit','plan-edit'].includes(action)){const list=action==='habit-edit'?model.habits:action==='goal-edit'?model.goals:model.plans,item=find(list,ref);if(!item)return;const name=prompt('Yangi nom',item.name);if(name===null||!name.trim())return;let extra=null;if(action==='goal-edit'){extra=prompt('Muddat (YYYY-MM-DD, bo‘sh bo‘lsa muddatsiz)',item.due);if(extra===null)return;if(extra&&!validDate(extra))return announce('Sana noto‘g‘ri. YYYY-MM-DD formatida kiriting.');}if(action==='plan-edit'){extra=prompt('Vaqt (HH:MM)',item.time);if(extra===null)return;if(!validTime(extra))return announce('Vaqt noto‘g‘ri. HH:MM formatida kiriting.');}change(()=>{item.name=safeString(name.trim(),action==='goal-edit'?240:120);if(action==='goal-edit')item.due=extra;if(action==='plan-edit')item.time=extra;});return;}
    if(action==='water-up')change(()=>d.water=Math.min(50,d.water+1));
    if(action==='water-down')change(()=>d.water=Math.max(0,d.water-1));
    if(action==='delete-habit'&&confirm('Odat o‘chirilsinmi?'))change(()=>{model.habits=model.habits.filter(x=>x.id!==ref);d.target=d.target.filter(x=>x!==ref);d.done=d.done.filter(x=>x!==ref)});
    if(action==='goal-delete'&&confirm('Maqsad o‘chirilsinmi?'))change(()=>model.goals=model.goals.filter(x=>x.id!==ref));
    if(action==='plan-delete'&&confirm('Reja o‘chirilsinmi?'))change(()=>model.plans=model.plans.filter(x=>x.id!==ref));
    if(action==='timer-toggle'){if(timer?.end){timer.left=Math.max(0,timer.end-Date.now());timer.end=null}else{if(!timer)timer={left:model.duration*60000,duration:model.duration,end:null};timer.end=Date.now()+timer.left;}persist();render()}
    if(action==='timer-reset'){timer=null;persist();render()}
    if(action==='challenge-start'){let n=Number(document.getElementById('challenge-length').value);change(()=>model.challenge={start:dateKey(),length:n})}
    if(action==='challenge-stop'&&confirm('Marafon tugatilsinmi?'))change(()=>model.challenge=null);
    if(action==='backup')exportBackup();
    if(action==='restore-text'){const el=document.getElementById('backup-text');try{if(el.value.length>2500000)throw Error('Too large');const val=JSON.parse(el.value);if(!val||!Array.isArray(val.habits)||!val.days)throw Error('bad');if(confirm('Joriy ma’lumotlar almashtirilsinmi?')){const incoming=normalize(val),before=model,oldTimer=timer,wasBlocked=storageBlocked;model=incoming;timer=model.focusTimer;storageBlocked=false;recovery='';persist();if(!storageOK){model=before;timer=oldTimer;storageBlocked=wasBlocked;throw Error('Storage failure');}syncAllReminders();render();announce('Zaxira tiklandi');}}catch(e){announce('Zaxira matni noto‘g‘ri');}}
    if(action==='reminder-status'){const el=document.getElementById('reminder-diagnostic');if(el){try{const report=JSON.parse(REM?.reminderStatus?.()||'{}');el.textContent=`Bildirishnoma: ${report.notifications?'ruxsat bor':'ruxsat yo‘q'}; aniq vaqt: ${report.exact?'mavjud':'cheklangan'}; faol: ${report.enabled??0} ta. Internet kerak emas.`;}catch(e){el.textContent='Android ilovasida tekshirib ko‘ring.';}}return;}
    if(action==='reminder-permission'){try{REM?.requestNotificationPermission?.();announce('Ruxsat so‘rovi ochildi.');}catch(e){announce('Ruxsat oynasi ochilmadi.')}return;}
    if(action==='exact-permission'){try{REM?.openExactAlarmSettings?.();announce('Android sozlamalari ochildi.');}catch(e){announce('Android sozlamalari ochilmadi.')}return;}
    if(action==='reminder-test'){try{announce(REM&&REM.testReminder()?'Test bildirishnomasi yuborildi.':'Telefon sozlamalarida INTIZOM PRO bildirishnomalariga ruxsat bering.')}catch(e){announce('Testni yuborib bo‘lmadi')}}
    if(action==='reminder-delete'){const r=model.reminders.find(x=>x.slot===Number(ref));if(r&&confirm('Eslatma o‘chirilsinmi?')){try{REM?.removeReminder(r.slot)}catch(e){}change(()=>model.reminders=model.reminders.filter(x=>x.slot!==r.slot))}}

  });
  document.addEventListener('submit',e=>{
    const form=e.target;if(!['habit-form','goal-form','plan-form','reminder-form','profile-form'].includes(form.id))return;e.preventDefault();
    if(form.id==='profile-form'){const name=form.querySelector('#profile-name').value.trim();if(!name)return announce('Ismingizni kiriting.');model.profile={name:safeString(name,50),style:form.querySelector('#profile-style').value==='friendly'?'friendly':'formal'};active='home';navStack=[];persist();syncAllReminders();render();announce(personal('profil saqlandi!'));return;}
    if(form.id==='reminder-form'){const name=form.querySelector('[name=name]').value.trim(),time=form.querySelector('[name=time]').value,slot=Array.from({length:32},(_,i)=>i).find(i=>!model.reminders.some(r=>r.slot===i));if(slot===undefined)return announce('32 ta eslatma limiti');if(name&&validTime(time)){const r={slot,name:safeString(name,100),time,on:true};const ok=syncReminder(r);change(()=>model.reminders.push(r));announce(ok?'Eslatma qo‘shildi':'Eslatma saqlandi. Bildirishnoma ruxsatini tekshiring.')}}
    if(form.id==='habit-form'){const name=form.querySelector('#habit-name').value.trim(),cat=form.querySelector('#habit-cat').value;if(!name)return;if(model.habits.length>=(window.IntizomSubscriptions?.current()?.id==='FREE'?5:300))return announce('FREE tarifida 5 ta odat limiti. Tariflar bo‘limini oching.');change(()=>{const h={id:id(),name:safeString(name,120),cat};model.habits.push(h);today().target.push(h.id)});}
    if(form.id==='goal-form'){const name=form.querySelector('[name=goal]').value.trim(),due=form.querySelector('[name=due]').value;if(model.goals.length>=500)return announce('500 ta maqsad limiti');if(name)change(()=>model.goals.push({id:id(),name:safeString(name,240),due,done:false}));}
    if(form.id==='plan-form'){const name=form.querySelector('[name=plan]').value.trim(),time=form.querySelector('[name=time]').value;if(model.plans.length>=300)return announce('300 ta reja limiti');if(name&&validTime(time))change(()=>model.plans.push({id:id(),name:safeString(name,120),time,completed:''}));}
  });
  document.addEventListener('change',e=>{
    const t=e.target,a=t.dataset.act,ref=t.dataset.id;if(t.id==='local-audio'||t.id==='local-video'){flushUsage();if(t.id==='local-audio')mediaSlot=+t.value;else videoSlot=+t.value;render();return;}if(t.id==='audio-select'||t.id==='video-select'){flushUsage();if(t.id==='audio-select')selectedAudio=t.value;else selectedVideo=t.value;render();return;}if(t.id==='playback-speed'){const player=document.getElementById('study-player');if(player)player.playbackRate=Number(t.value);return;}const d=today();
    if(a==='reminder-toggle'||a==='reminder-time'){const r=model.reminders.find(x=>x.slot===Number(ref));if(r){if(a==='reminder-toggle')r.on=t.checked;else if(validTime(t.value))r.time=t.value;const ok=syncReminder(r);persist();render();announce(ok?(r.on?'Eslatma sozlandi':'Eslatma o‘chirildi'):'Bildirishnoma ruxsatini tekshiring.')}}
    if(t.id==='water-goal'){change(()=>model.waterGoal=Math.min(20,Math.max(1,Math.round(Number(t.value)||8))))}
    if(a==='toggle-habit')change(()=>{const val=ref;d.done=t.checked?[...new Set([...d.done,val])]:d.done.filter(x=>x!==val)});
    if(a==='goal-toggle')change(()=>{const g=find(model.goals,ref);if(g)g.done=t.checked});
    if(a==='plan-toggle')change(()=>{const p=find(model.plans,ref);if(p)p.completed=t.checked?dateKey():''});
    if(t.id==='duration'&&!timer&&[5,15,25,50,90].includes(Number(t.value)))change(()=>model.duration=Number(t.value));
    if(t.id==='mood')change(()=>d.mood=t.value);
    if(t.id==='appearance')change(()=>model.appearance=t.value);
    if(t.id==='restore-file')importBackup(t.files?.[0]);
  });
  document.addEventListener('input',e=>{if(e.target.id==='book-search'){const q=e.target.value.trim().toLocaleLowerCase();let count=0;document.querySelectorAll('.book-row').forEach(r=>{r.hidden=!r.dataset.bookName.toLocaleLowerCase().includes(q);if(!r.hidden)count++;});document.getElementById('book-no-results').hidden=!!count;return;}if(e.target.id==='journal'){today().note=safeString(e.target.value,4000);persist();}});
  document.addEventListener('keydown',e=>{if(active!=='reader'||!pdfCount)return;if(e.target?.id==='pdf-number'&&e.key==='Enter'){e.preventDefault();studyAction('pdf-jump');return;}if(/^(INPUT|TEXTAREA|SELECT|BUTTON)$/.test(e.target?.tagName||''))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();studyAction(e.key==='ArrowLeft'?'pdf-prev':'pdf-next');}});
  const firstDate=dateKey();today();persist();if(storageBlocked){active='settings';navStack=['home','more'];}else if(!profileName()){active='profile';navStack=['home'];}render();if(recovery)announce(recovery);if(!storageBlocked){recovery='';syncAllReminders();}setInterval(updateClock,300);
  let lastDate=firstDate;setInterval(()=>{if(dateKey()!==lastDate){lastDate=dateKey();flushUsage();today();render();}},20000);
  window.addEventListener('pagehide',()=>{flushUsage();});
  setInterval(sampleUsage,1000);let lastDlPoll='';setInterval(()=>{if(document.hidden)return;if(active==='library'){for(const i of catalogSlots){const e=document.getElementById('dl-'+i);if(e)e.textContent=dlLabel(dlState(i));}}else if(active==='reader'&&!pdfReady&&!bundled(currentBook)&&catalogSlots.includes(currentBook)){const s=dlState(currentBook),key=currentBook+':'+s;if(key!==lastDlPoll){lastDlPoll=key;showPdf();}}},2000);
  document.addEventListener('visibilitychange',()=>{if(document.hidden)saveMediaPosition();lastTrack=Date.now();trackRemainder=0;mediaLast=null;mediaCarry=0;persist();});
  document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateClock();if(dateKey()!==lastDate){lastDate=dateKey();flushUsage();today();render();}}else persist();});
  const launch=document.getElementById('launch-screen');if(launch){const dismiss=()=>{launch.hidden=true;lastTrack=Date.now();trackRemainder=0;};launch.addEventListener('click',dismiss,{once:true});setTimeout(dismiss,1400);}
